import 'package:flutter/cupertino.dart';import 'package:flutter_screenutil/flutter_screenutil.dart';import 'package:zan/Core/Resources/app_colors.dart';import '../../../../Core/Utils/Extensions/responsive_extension.dart';import '../../../../Config/Assets/images.dart';class AuthenticationSplit1 extends StatelessWidget {  const AuthenticationSplit1({super.key});  @override  Widget build(BuildContext context) {    final bool isSmall = context.isSmallScreen;    return Align(      alignment: isSmall ? Alignment.topCenter : Alignment.centerRight,      child: Container(        color: AppColors.white,        width: isSmall ? 1.sw : 0.5.sw,        child: AspectRatio(          aspectRatio: 1,          child: Row(            children: [              _buildImageColumn(                  [AppImages.image7, AppImages.image8, AppImages.image9]),              _buildImageColumn(                  [AppImages.image4, AppImages.image6, AppImages.image5]),              _buildImageColumn(                  [AppImages.image1, AppImages.image2, AppImages.image3]),            ],          ),        ),      ),    );  }  Widget _buildImageColumn(List<String> imagePaths) {    return Expanded(      child: Column(        children: imagePaths.map((path) => _buildImage(path)).toList(),      ),    );  }  Widget _buildImage(String imagePath) {    return Expanded(      child: Image.asset(        imagePath,        fit: BoxFit.contain,      ),    );  }}